-- composition of rule kernels common_subplan x window_self_join (duckdb), template not_exists
SELECT count(*) FROM (SELECT 1.0::float8 AS c0, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c1, a1.c0 AS c2, '2000-01-01'::date AS c3 FROM tl AS a1 WHERE NULLIF ((NOT COALESCE (FALSE, (EXISTS (SELECT FALSE AS c0)))), TRUE)) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT AGE ((MAX ('2024-01-01 00:00:00+00'::timestamptz) OVER () - '0'::interval), '2024-02-29 12:34:56+00'::timestamptz) AS c0, 10 AS c1, 2 AS c2) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT AGE ((MAX ('2024-01-01 00:00:00+00'::timestamptz) OVER () - '0'::interval), '2024-02-29 12:34:56+00'::timestamptz) AS c0, 10 AS c1, 2 AS c2) AS kb) = 0 THEN (SELECT count(*) FROM (SELECT 1.0::float8 AS c0, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c1, a1.c0 AS c2, '2000-01-01'::date AS c3 FROM tl AS a1 WHERE NULLIF ((NOT COALESCE (FALSE, (EXISTS (SELECT FALSE AS c0)))), TRUE)) AS ka) ELSE 0 END
